function schedule(principal, annualRate, periods){
  var r = annualRate/12; // monthly rate
  var n = periods;
  var pmt = (r===0) ? principal/n : principal*r/(1-Math.pow(1+r,-n));
  var rows=[]; var bal=principal;
  for(var i=1;i<=n;i++){
    var interest = bal*r;
    var principalPart = pmt - interest;
    bal -= principalPart;
    if(i===n) bal = 0; // clamp rounding
    rows.push({period:i, payment:pmt, interest:interest, principal:principalPart, balance:Math.max(bal,0)});
  }
  return {pmt:pmt, rows:rows};
}
var EXPORTS = { schedule:schedule };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AmortizationForgePure = EXPORTS; }
